  "theme-init.js": { content: "// Applies the saved theme before first paint. Loaded as a blocking external script so the\n// admin's Content-Security-Policy (script-src 'self') allows it and there is no flash.\n(function () {\n  try {\n    var stored = localStorage.getItem(\"bakorin_theme\");\n    var mode = stored === \"light\" || stored === \"dark\" || stored === \"system\" ? stored : \"system\";\n    var dark =\n      mode === \"dark\" ||\n      (mode !== \"light\" && window.matchMedia(\"(prefers-color-scheme: dark)\").matches);\n    var theme = dark ? \"dark\" : \"light\";\n    document.documentElement.setAttribute(\"data-theme\", theme);\n    document.documentElement.setAttribute(\"data-theme-mode\", mode);\n    document.documentElement.style.colorScheme = theme;\n  } catch (err) {\n    document.documentElement.setAttribute(\"data-theme\", \"light\");\n    document.documentElement.setAttribute(\"data-theme-mode\", \"system\");\n  }\n})();\n", encoding: "utf8" }
